'use strict';
let currentFlow=null,flowItems=[],flowGroup='主线流程',auditCode=0x8959;
const readableText=value=>value.replace(/\{#[0-9a-f]+\}/gi,'').replace(/　+/g,' ').trim();
function nativePreviewValue(entry){if(model.textEdits.has(entry.key))return model.textValue(entry);return entry.text.tokens.map(t=>t.control?`{#${t.raw.map(b=>E.hex(b,2)).join('')}}`:t.code>=0x8000?`{字${E.hex(t.code,4)}}`:String.fromCharCode(t.code)).join('');}
function drawPortrait(canvas,id,expression=1){if(!canvas)return;canvas.width=80;canvas.height=80;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,80,80);canvas.title=actorName(id);if(id>0&&id<=60){try{const img=model.renderPortrait(id,expression);ctx.putImageData(new ImageData(img.pixels,80,80),0,0);if(!img.placeholder)return;canvas.title+='（原游戏共用占位头像）';}catch(e){canvas.title=e.message;}}
 ctx.fillStyle='#e8eee1';ctx.fillRect(0,0,80,80);ctx.fillStyle='#54715a';ctx.font='13px sans-serif';ctx.textAlign='center';ctx.fillText(id>=250?'队伍位置':id?'无独立头像':'空位',40,44);
}
function paintPortraits(container){container.querySelectorAll('[data-portrait]').forEach(c=>drawPortrait(c,+c.dataset.portrait));}
function initializeFlow(){flowItems=model.flowItems();flowGroup=model.rom[0x8f698]>=56?'少年篇续章':'主线流程';$('#flowGroup').innerHTML=[...new Set(flowItems.map(x=>x.group))].map(g=>`<option>${esc(g)}</option>`).join('');$('#flowGroup').disabled=false;$('#flowGroup').onchange=e=>{flowGroup=e.target.value;renderFlowList();};
 $('#stage').innerHTML=model.sceneIds().map(s=>{const name=model.battleIds().includes(s)?readableText(model.textValue(model.missionTexts(s,0)[0])):({50:'火影办公室 / 忍者学校',51:'达兹纳家',52:'中忍考试会场',53:'死亡森林中央塔',54:'一乐拉面'}[s]||'占位 / 不可进入');return `<option value="${s}">${model.battleIds().includes(s)?'战场':'剧情'} ${s} · ${esc(name)}</option>`;}).join('');
 const initial=model.rom[0x8f698],first=flowItems.find(x=>x.group===flowGroup&&x.scene===(initial>=56?initial:initial===1?1:54));selectFlow(first||flowItems[0]);
}
function renderFlowList(){const items=flowItems.filter(x=>x.group===flowGroup);$('#flowList').innerHTML=items.map((x,i)=>`<button type="button" role="listitem" data-flow="${esc(x.id)}" class="flowstep ${currentFlow?.id===x.id?'selected':''}"><span class="flowtype ${x.kind}">${x.kind==='battle'?'战场':x.kind==='branch'?'分支':'剧情'}</span><span>${esc(x.title)}</span><small>${x.kind==='battle'?'战场':'剧情'} ${x.scene}${x.part==='after'?' · 战后':''}</small></button>`).join('');$('#flowList').querySelectorAll('button').forEach(b=>b.onclick=()=>selectFlow(flowItems.find(x=>x.id===b.dataset.flow)));}
function selectFlow(item){currentFlow=item;stage=item.scene;page=0;search='';$('#stage').value=stage;flowGroup=item.group;$('#flowGroup').value=flowGroup;tab=item.kind==='story'?'dialogue':'actors';dialoguePart=item.part||'all';renderFlowList();render();updateStatus();}
function renderFlowHeading(){const chapters=new Map((model.campaignData?.()?.chapters||[]).map(c=>[c.id,c]));for(const item of flowItems)if(item.id.startsWith('campaign:')){const c=chapters.get(item.scene);if(c)item.title=`${c.title} · ${item.kind==='battle'?'战场':item.part==='after'?'战后':'战前'}`;}const h=$('#flowHeading');h.hidden=false;const native=`内部${model.battleIds().includes(stage)?'战场':'剧情'} ${stage}`,items=flowItems.filter(x=>x.group===(currentFlow?.group||flowGroup)),index=items.findIndex(x=>x.id===currentFlow?.id);h.innerHTML=`<div><b>${esc(currentFlow?.title||native)}</b><p>${currentFlow?`${currentFlow.kind==='battle'?'编辑实际战斗配置':'编辑此处剧情'} · ${native}`:`同编号的战前、战斗、战后共用这个关卡。独立地点剧情可由多个进度调用。`}</p></div><div class="toolbar"><button id="flowPrev" ${index<=0?'disabled':''}>← 上一段</button><button id="flowNext" ${index<0||index>=items.length-1?'disabled':''}>下一段 →</button></div>`;$('#flowPrev').onclick=()=>selectFlow(items[index-1]);$('#flowNext').onclick=()=>selectFlow(items[index+1]);renderFlowList();}
function drawRawGlyph(canvas,code,scale=8){const g=E.glyph(model.rom,code);canvas.width=8*scale;canvas.height=16*scale;const c=canvas.getContext('2d');c.fillStyle='#f5f7ed';c.fillRect(0,0,canvas.width,canvas.height);if(!g)return;for(let y=0;y<16;y++)for(let x=0;x<8;x++){const v=g[y*2+(x>>2)]>>((x&3)*2)&3;if(v){c.fillStyle=v===3?'#263c2c':v===1?'#899575':'#c7cfad';c.fillRect(x*scale,y*scale,scale,scale);}}}
function renderGlyphAudit(){const code=auditCode,label=model.mapping[code]||'',corrected=model.exportFeatures().glyphCorrections?.[code],confirmed=E.textCatalog.confirmed[code],prior=E.textCatalog.previousInference[code],used=new Map();for(let s=1;s<=55;s++)for(const e of model.dialogues(s))for(const t of e.text.tokens)if(t.code>=0x8000&&!model.mapping[t.code])used.set(t.code,(used.get(t.code)||0)+1);
 panel.innerHTML=`<div class="sectionhead"><div><h2>字形与中文校对</h2><p>直接查看 ROM 的原字形，比较推断，并保存你确认的对应字。</p></div><span class="badge">${Object.keys(E.textCatalog.confirmed).length} 个用户确认的固定对照</span></div><div class="card"><div class="glyphaudit"><canvas id="auditGlyph"></canvas><div><label>原字码（十六进制）<input id="auditCode" value="${E.hex(code,4)}" maxlength="4"></label><div class="toolbar"><button id="auditPrev">前一个</button><button id="auditOpen">查看字形</button><button id="auditNext">后一个</button></div><p>当前中文：<strong id="auditCurrent">${esc(label||'待识别')}</strong>　${corrected?'已在本工程校对':confirmed?'你已确认':'字序 / 上下文推断，待校对'}</p>${prior?`<p>先前推断：<s>${esc(prior)}</s>　→　你确认：<b>${esc(confirmed)}</b></p>`:''}<label>确认应当显示为哪个字？<input id="auditLabel" value="${esc(label)}" maxlength="2"></label><button id="saveGlyph" class="primary">保存中文对应</button></div></div><p class="hint">校对只调整字码与中文的对应关系，原字形图案保持原样。工程会记录校对结果；导出 ROM 时也会附带字表目录，重新打开仍可识别。</p></div><div class="card"><h3>对白中仍待识别的字形</h3><p class="hint">选择字码查看原图。这里只统计对白；同一共享片段可能出现在多个剧情入口。</p><div class="toolbar">${[...used].sort((a,b)=>a[0]-b[0]).slice(0,100).map(([c,n])=>`<button class="auditUnknown" data-code="${c}">${E.hex(c,4)} · ${n} 处</button>`).join('')||'已找到中文对照；推断项仍需人工检查。'}</div></div>`;
 drawRawGlyph($('#auditGlyph'),code);const jump=c=>{if(!E.glyph(model.rom,c))throw Error('此字码没有原字形');auditCode=c;renderGlyphAudit();};$('#auditOpen').onclick=()=>run(()=>{if(!/^[0-9a-f]{4}$/i.test($('#auditCode').value.trim()))throw Error('请输入四位十六进制字码，例如 8959');jump(parseInt($('#auditCode').value,16));});$('#auditPrev').onclick=()=>run(()=>jump(code-1));$('#auditNext').onclick=()=>run(()=>jump(code+1));$('#saveGlyph').onclick=()=>run(()=>transaction('校对原字形对应的中文',()=>model.setGlyphLabel(code,$('#auditLabel').value.trim())));panel.querySelectorAll('.auditUnknown').forEach(b=>b.onclick=()=>run(()=>jump(+b.dataset.code)));
}

let glyphAuditPending=false;
function syncGlyphTab(){const b=document.querySelector('[data-tab=glyphs]');if(b)b.hidden=!glyphAuditPending&&tab!=='glyphs';}
window.addEventListener('romloaded',()=>{glyphAuditPending=false;for(const segment of E.fontSegments(model.rom))for(let code=segment.start;code<segment.start+segment.count;code++){if(model.mapping[code])continue;const raw=E.glyph(model.rom,code);if(raw.some(v=>v)&&!raw.every(v=>v===255))glyphAuditPending=true;}$('#openGlyphAudit').disabled=false;$('#glyphAuditStatus').textContent=glyphAuditPending?'当前字库仍有待对应的字形。':'此前待识别字形已补齐，需要纠错时再打开。';syncGlyphTab();});
$('#openGlyphAudit').onclick=()=>{tab='glyphs';render();};
